def price_book(customer, market):
    """Risk-hedged, segment-tailored pricing with demand-response value sharing and load-flexibility exposure."""
    seg = customer["segment"]
    energy = energy_cost_jpy_kwh(customer, market)
    other = non_energy_cost_jpy_kwh(customer, market)
    wheeling_basic = wheeling_basic_jpy_kw_month(customer, market)

    # 1. Calibrate market-linked share (alpha) based on risk appetite and load flexibility
    risk_app = customer.get("risk_appetite", "medium")
    flex_share = customer.get("flex_share", 0.0)

    if risk_app == "high":
        base_alpha = 0.55
    elif risk_app == "medium":
        base_alpha = 0.38
    else:
        base_alpha = 0.22

    if seg == "data_center":
        base_alpha = max(base_alpha, 0.50)

    if flex_share > 0.05:
        base_alpha += min(0.12, flex_share * 0.5)

    alpha = clamp(base_alpha, 0.10, 0.65)

    # Invariant 1: Essential facilities cap
    if customer.get("essential", False) or seg in ("hospital", "water_utility"):
        alpha = min(alpha, 0.30)

    # 2. Segment & procurement differentiated margins to prevent churn breaches
    procurement = customer.get("procurement_style", "negotiated")
    if seg == "water_utility":
        margin = 0.70
    elif seg == "semiconductor_fab":
        margin = 0.72
    elif seg == "university":
        margin = 0.82
    elif seg == "data_center":
        margin = 0.82
    elif seg == "hospital":
        margin = 0.95
    elif procurement == "tender":
        margin = 0.85
    elif procurement == "auto_renew":
        margin = 1.28
    else:
        margin = 1.12

    energy_rate = round(energy + other + margin, 3)
    market_adder = round(other + margin, 3)
    demand_charge = round(wheeling_basic + 28.0, 1)

    # 3. Share DR value to incentivize enrollment and gain peak curtailment value
    dr_discount = 0.0
    if customer.get("dr_potential_kw", 0.0) > 0 and customer.get("dr_interest", False):
        dr_val_annual = market.get("dr_value_estimate_jpy_per_kw_year", 3000.0)
        dr_discount = round(clamp((dr_val_annual / 12.0) * 0.45, 0.0, 300.0), 1)

    return {
        "energy_rate_jpy_kwh": energy_rate,
        "alpha": round(alpha, 2),
        "market_adder_jpy_kwh": market_adder,
        "demand_charge_jpy_kw_month": demand_charge,
        "deviation_band_pct": 10.0,
        "deviation_penalty_jpy_kwh": 0.4,
        "dr_discount_jpy_kw_month": dr_discount,
        "term_years": 1,
    }

def price_book(customer, market):
    """Risk-hedged, segment-tailored pricing with demand-response value sharing and term optimization."""
    seg = customer["segment"]
    energy = energy_cost_jpy_kwh(customer, market)
    other = non_energy_cost_jpy_kwh(customer, market)
    wheeling_basic = wheeling_basic_jpy_kw_month(customer, market)

    # 1. Market-linked share (alpha) calibrated to customer risk appetite & flexible load
    risk_app = customer.get("risk_appetite", "medium")
    flex_share = customer.get("flex_share", 0.0)

    if risk_app == "high":
        base_alpha = 0.73
    elif risk_app == "medium":
        base_alpha = 0.51
    else:
        base_alpha = 0.23

    if seg == "data_center":
        base_alpha = max(base_alpha, 0.65)
    if flex_share > 0.05:
        base_alpha += min(0.20, flex_share * 0.95)

    alpha = clamp(base_alpha, 0.10, 0.78)

    # Invariant 1: Essential facilities cap
    if customer.get("essential", False) or seg in ("hospital", "water_utility"):
        alpha = min(alpha, 0.30)

    # 2. Segment & procurement style margin targeting to protect churn guard bands (<=22%)
    procurement = customer.get("procurement_style", "negotiated")
    if seg == "water_utility":
        margin = 0.68
    elif seg == "semiconductor_fab":
        margin = 0.66
    elif seg == "university":
        margin = 0.82
    elif seg == "data_center":
        margin = 0.85
    elif procurement == "tender":
        margin = 0.78
    elif procurement == "auto_renew":
        margin = 1.35
    else:
        margin = 1.18

    energy_rate = round(energy + other + margin, 3)
    market_adder = round(other + margin, 3)
    demand_charge = round(wheeling_basic + 26.0, 1)

    # 3. Demand Response value sharing (72% to customer)
    dr_discount = 0.0
    if customer.get("dr_potential_kw", 0.0) > 0 and customer.get("dr_interest", False):
        dr_val_annual = market.get("dr_value_estimate_jpy_per_kw_year", 3000.0)
        dr_discount = round(clamp((dr_val_annual / 12.0) * 0.72, 0.0, 300.0), 1)

    # 4. Term duration optimization: restrict multi-year terms to high-alpha (alpha >= 0.70) customers
    term_hint = customer.get("preferred_term_hint", 1)
    if term_hint in (2, 3) and alpha >= 0.70 and procurement != "tender":
        term_years = 2
    else:
        term_years = 1

    return {
        "energy_rate_jpy_kwh": energy_rate,
        "alpha": round(alpha, 2),
        "market_adder_jpy_kwh": market_adder,
        "demand_charge_jpy_kw_month": demand_charge,
        "deviation_band_pct": 10.0,
        "deviation_penalty_jpy_kwh": 0.4,
        "dr_discount_jpy_kw_month": dr_discount,
        "term_years": term_years,
    }
